        long long da = a % k;
        long long db = b % k;
        long long dc = c % k;

        if ((da + db) % k != dc) return false;

        a /= k;
        b /= k;
        c /= k;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        long long a, b, c;
        cin >> a >> b >> c;

        long long d = a + b - c;

        if (d < 0) {
            cout << 0 << '\n';
        } else if (d == 0) {
            cout << -1 << '\n';
        } else {
            int answer = 0;
            for (long long i = 1; i * i <= d; ++i) {
                if (d % i != 0) continue;

                long long j = d / i;
                if (i >= 2 && valid(i, a, b, c)) ++answer;
                if (j != i && j >= 2 && valid(j, a, b, c)) ++answer;
            }
            cout << answer << '\n';
        }
    }
    return 0;
}
```

### 对两份回答的评价

Assistant B 的核心思路和代码正确：利用 \(a+b-c=kM\) 将候选进制限制为 \(d\) 的因子，再逐位验证；对 \(d<0\)、\(d=0\) 的处理也符合题意。它给出的样例 2 分析正确。伪代码里“while(a,b,c 都不为 0)”的表述不够准确，但实际代码使用 `A > 0 || B > 0 || C > 0`，正确处理了高位补零，因而不影响实现。

